#!/usr/bin/env python3
"""Regression tests for the WireGuard timestamp guard generated by vless.sh."""
from pathlib import Path
import subprocess
import time
import unittest

SCRIPT = Path(__file__).resolve().parents[1] / "vless.sh"
MARKER = "    # WG may handshake after the sweep started; use the time of this check."

class WGHandshakeClockTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        source = SCRIPT.read_text()
        assert source.count(MARKER) == 1
        start = source.index(MARKER)
        cls.guard = source[start:source.index("\n    fi", start) + len("\n    fi")]

    def check(self, handshake, sweep_offset=0):
        script = (
            "probe() {\n"
            f"local now={int(time.time()) + sweep_offset} tag=test wg_if=wg-nat "
            f"handshake_max=180 hs={handshake!r}\n"
            f"{self.guard}\n"
            "}\nprobe\n"
        )
        return subprocess.run(["bash", "-c", script], capture_output=True).returncode

    def test_new_handshake_after_sweep_start(self):
        self.assertEqual(self.check(int(time.time()), sweep_offset=-30), 0)

    def test_recent_handshake(self):
        self.assertEqual(self.check(int(time.time()) - 90), 0)

    def test_stale_handshake(self):
        self.assertNotEqual(self.check(int(time.time()) - 240), 0)

    def test_future_handshake(self):
        self.assertNotEqual(self.check(int(time.time()) + 240), 0)

    def test_invalid_handshakes(self):
        for value in ("", "0", "-1", "invalid"):
            with self.subTest(value=value):
                self.assertNotEqual(self.check(value), 0)

if __name__ == "__main__":
    unittest.main()
